(2989772, 420916, 16241, '<td valign="top">i like!</td>', 'i like!', '2006-11-02 15:46:29.000000', NULL, 1),
(2989774, 417927, 811, '<td valign="top">Awesome awesome.  I looks like something is exploding or breaking away to show the steeple.  Very cool.</td>', 'Awesome awesome.  I looks like something is exploding or breaking away to show the steeple.  Very cool.', '2006-11-02 15:46:49.000000', NULL, 1),
