(2989832, 420511, 23484, '<td valign="top">Excelent portrait. The softness is great. 8</td>', 'Excelent portrait. The softness is great. 8', '2006-11-02 16:06:07.000000', NULL, 1),
(2989836, 406544, 50695, '<td valign="top">Brilliant plan. Brilliant execution. Just like Joe Montana''s 49ers. I''ll give this a 10 for now and maybe bump it up later. I mean... this is such a poem... it ripples with themes of death, identity, information, society... my mind is spinning... it''s everything I can do to keep myself from writing a novel about it right now...</td>', 'Brilliant plan. Brilliant execution. Just like Joe Montana''s 49ers. I''ll give this a 10 for now and maybe bump it up later. I mean... this is such a poem... it ripples with themes of death, identity, information, society... my mind is spinning... it''s everything I can do to keep myself from writing a novel about it right now...', '2006-11-02 16:06:48.000000', NULL, 1),
(2989846, 411267, 50695, '<td valign="top">7 for storytelling.</td>', '7 for storytelling.', '2006-11-02 16:08:20.000000', NULL, 1),
(2989858, 406780, 50695, '<td valign="top">Nice composition. 7</td>', 'Nice composition. 7', '2006-11-02 16:10:54.000000', NULL, 1),
