(2990989, 415695, 23002, '<td valign="top">very creative composition.</td>', 'very creative composition.', '2006-11-02 20:06:40.000000', NULL, 1),
(2990991, 420927, 811, '<td valign="top">Very cool picture.  I like the silhouette of the boarder, the frozen motion of the water and the yellow sky.  Nicely done.  Reminds me of the pictures seen on the motivational posters. . .</td>', 'Very cool picture.  I like the silhouette of the boarder, the frozen motion of the water and the yellow sky.  Nicely done.  Reminds me of the pictures seen on the motivational posters. . .', '2006-11-02 20:07:24.000000', NULL, 1),
