(2991339, 421060, 43774, '<td valign="top">Wonderful clarity, beautiful colour</td>', 'Wonderful clarity, beautiful colour', '2006-11-02 21:32:09.000000', NULL, 1),
(2991341, 418817, 35513, '<td valign="top">Nice motion on the flames, but I wish there were perhaps a secondary subject to hold my attention as well.</td>', 'Nice motion on the flames, but I wish there were perhaps a secondary subject to hold my attention as well.', '2006-11-02 21:32:19.000000', NULL, 1),
