(2991350, 408018, 35513, '<td valign="top">Beautiful scene!  Great sunset and a lovely silhouette.</td>', 'Beautiful scene!  Great sunset and a lovely silhouette.', '2006-11-02 21:34:15.000000', NULL, 1),
(2991351, 420725, 43774, '<td valign="top">Great perspective. I like the tones. I would have cloned out that speck in the sky. Sky looks a bit grainy.</td>', 'Great perspective. I like the tones. I would have cloned out that speck in the sky. Sky looks a bit grainy.', '2006-11-02 21:34:29.000000', NULL, 1),
