(2991357, 418764, 43774, '<td valign="top">Amazing colours and clarity here. Bird is a bit too small to make an impact.</td>', 'Amazing colours and clarity here. Bird is a bit too small to make an impact.', '2006-11-02 21:35:24.000000', NULL, 1),
(2991358, 417081, 43774, '<td valign="top">Wonderful colours!!</td>', 'Wonderful colours!!', '2006-11-02 21:35:39.000000', NULL, 1),
