(2995836, 413446, 35804, '<td valign="top">Love the greened color...completely fits the atmosphere...a cool fun shot.</td>', 'Love the greened color...completely fits the atmosphere...a cool fun shot.', '2006-11-03 20:44:01.000000', NULL, 1),
(2995838, 419135, 4226, '<td valign="top">Very hard to expose inside a church and you did a great job with not letting the windows blow out!</td>', 'Very hard to expose inside a church and you did a great job with not letting the windows blow out!', '2006-11-03 20:44:18.000000', NULL, 1),
(2995839, 414525, 811, '<td valign="top">Cool lighting effects.</td>', 'Cool lighting effects.', '2006-11-03 20:44:34.000000', NULL, 1),
