(2999044, 411415, 50357, '<td valign="top">What incredible detail!  Very nice</td>', 'What incredible detail!  Very nice', '2006-11-04 22:01:10.000000', NULL, 1),
(2999045, 404955, 50357, '<td valign="top">This is such a cool shot!   9</td>', 'This is such a cool shot!   9', '2006-11-04 22:02:06.000000', NULL, 1),
