INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3002774, 420810, 58800, '<td valign="top">great night cityscape, but the foreground seems a little messy and adds nothing to the image.</td>', 'great night cityscape, but the foreground seems a little messy and adds nothing to the image.', '2006-11-05 17:19:44.000000', NULL, 1),
(3002775, 421024, 35513, '<td valign="top">Great detail on this shot, though the backlighting makes it hard to see some of the colors on the bird.  Still, a nice capture!</td>', 'Great detail on this shot, though the backlighting makes it hard to see some of the colors on the bird.  Still, a nice capture!', '2006-11-05 17:19:44.000000', NULL, 1),
(3002777, 420589, 39144, '<td valign="top">Interesting expression. The lighting is awesome, and the tilted head really goes well with the wacky eyes.</td>', 'Interesting expression. The lighting is awesome, and the tilted head really goes well with the wacky eyes.', '2006-11-05 17:19:59.000000', NULL, 1),
(3002778, 420725, 35513, '<td valign="top">Very dramatic!  I like the blue tones in this shot a lot....gives a cool feeling that I really associate with this kind of scene.</td>', 'Very dramatic!  I like the blue tones in this shot a lot....gives a cool feeling that I really associate with this kind of scene.', '2006-11-05 17:20:18.000000', NULL, 1),
(3002779, 421097, 58800, '<td valign="top">a good idea to just shoot the reflection and i like the colours that you have managed to capture.</td>', 'a good idea to just shoot the reflection and i like the colours that you have managed to capture.', '2006-11-05 17:20:21.000000', NULL, 1),
(3002780, 421089, 35513, '<td valign="top">Very beautiful colors!!  I know the land line falls along thirds, but I think I would have preferred a bit more space above the tree in the center.</td>', 'Very beautiful colors!!  I know the land line falls along thirds, but I think I would have preferred a bit more space above the tree in the center.', '2006-11-05 17:20:55.000000', NULL, 1),
