(3008951, 412163, 35513, '<td valign="top">Great exposure and very nice B&amp;W tones here!</td>', 'Great exposure and very nice B&W tones here!', '2006-11-07 00:15:00.000000', NULL, 1),
(3008953, 419325, 35513, '<td valign="top">Good colors and lighting on these leaves.</td>', 'Good colors and lighting on these leaves.', '2006-11-07 00:15:16.000000', NULL, 1),
(3008955, 420119, 35513, '<td valign="top">I like how the eyes really seem to be at eye level with the viewer--nicely done.</td>', 'I like how the eyes really seem to be at eye level with the viewer--nicely done.', '2006-11-07 00:15:37.000000', NULL, 1),
(3008956, 405255, 35513, '<td valign="top">Love the vibrant colors here!</td>', 'Love the vibrant colors here!', '2006-11-07 00:15:52.000000', NULL, 1),
